import { SubjectId } from '@/domain/SubjectId';

export enum ValueType {

	String = 'string',
	Url = 'url',
	Number = 'number',
	Boolean = 'boolean',
	Relation = 'relation',
	MonolingualText = 'monolingualText',

	/**
	 * Placeholder for a Value whose property type is not registered (e.g. owned
	 * by a disabled or failed extension). The raw stored data is preserved so it
	 * remains visible and round-trips on save instead of being lost.
	 */
	UnregisteredType = 'unregisteredType',

}

export interface BaseValueRepresentation {
	readonly type: ValueType;
}

export interface StringValue extends BaseValueRepresentation {
	readonly type: ValueType.String;
	readonly parts: string[];
}

export interface UrlEntry {
	url: string;
	label?: string;
	caption?: string;
	captionPage?: string;
}

export interface UrlValue extends BaseValueRepresentation {
	readonly type: ValueType.Url;
	readonly parts: UrlEntry[];
}

export function newUrlValue( input: unknown, allowIncomplete = false ): UrlValue {
	const parts = typeof input === 'string' ? [ input ] : input;
	if ( !Array.isArray( parts ) ) {
		throw new Error( 'URL values must be a list' );
	}
	return { type: ValueType.Url, parts: parts.map( ( raw: unknown ): UrlEntry => {
		if ( typeof raw === 'string' ) {
			return { url: raw.trim() };
		}
		if ( !raw || typeof raw !== 'object' || Array.isArray( raw ) ) {
			throw new Error( 'Invalid URL entry' );
		}
		const entry = raw as Record<string, unknown>;
		if ( typeof entry.url !== 'string' || Object.keys( entry ).some( ( key ) => ![ 'url', 'label', 'caption', 'captionPage' ].includes( key ) ) ) {
			throw new Error( 'Invalid URL entry' );
		}
		const result: UrlEntry = { url: entry.url.trim() };
		for ( const key of [ 'label', 'caption', 'captionPage' ] as const ) {
			if ( entry[ key ] !== undefined ) {
				if ( typeof entry[ key ] !== 'string' ) {
					throw new Error( 'URL fields must be text' );
				}
				const text = ( entry[ key ] as string ).trim();
				if ( text ) {
					result[ key ] = text;
				}
			}
		}
		if ( !allowIncomplete && !result.url && Object.keys( result ).length > 1 ) {
			throw new Error( 'A labelled URL needs an address' );
		}
		return result;
	} ).filter( ( entry ) => entry.url !== '' || allowIncomplete && Object.keys( entry ).length > 1 ) };
}

export function urlEntries( value: Value | undefined ): UrlEntry[] {
	return value?.type === ValueType.Url ? value.parts : value?.type === ValueType.String ? value.parts.map( ( url ) => ( { url } ) ) : [];
}

export interface NumberValue extends BaseValueRepresentation {
	readonly type: ValueType.Number;
	readonly number: number;
}

export interface BooleanValue extends BaseValueRepresentation {
	readonly type: ValueType.Boolean;
	readonly boolean: boolean;
}

export class RelationValue implements BaseValueRepresentation {
	public readonly type = ValueType.Relation;

	public constructor(
		public readonly relations: Relation[],
	) {
	}

	public get targetIds(): SubjectId[] {
		return this.relations.map( ( relation ) => relation.target );
	}
}

export class Relation {

	public constructor(
		public readonly id: string | undefined,
		public readonly target: SubjectId,
	) {
	}

}

/**
 * A text and the language it is in. The language is a well-formed BCP 47 tag, lowercased.
 */
export interface MonolingualText {
	readonly text: string;
	readonly language: string;
}

export interface MonolingualTextValue extends BaseValueRepresentation {
	readonly type: ValueType.MonolingualText;
	readonly parts: MonolingualText[];
}

export interface UnregisteredTypeValue extends BaseValueRepresentation {
	readonly type: ValueType.UnregisteredType;
	readonly typeName: string;
	readonly raw: unknown;
}

export type Value = UrlValue | StringValue | NumberValue | BooleanValue | RelationValue | MonolingualTextValue | UnregisteredTypeValue;

export function newStringValue( ...parts: string[] | [ string[] ] ): StringValue {
	const resolved = Array.isArray( parts[ 0 ] ) ? parts[ 0 ] : parts as string[];

	return {
		type: ValueType.String,
		parts: resolved
			.map( ( part ) => part.trim() )
			.filter( ( part ) => part !== '' ),
	} as StringValue;
}

export function newMonolingualTextValue( parts: MonolingualText[] ): MonolingualTextValue {
	return {
		type: ValueType.MonolingualText,
		parts: parts
			.map( ( part ) => ( { text: part.text.trim(), language: part.language.toLowerCase() } ) )
			.filter( ( part ) => part.text !== '' ),
	};
}

export function newNumberValue( number: number ): NumberValue {
	return {
		type: ValueType.Number,
		number: number,
	} as NumberValue;
}

export function newBooleanValue( boolean: boolean ): BooleanValue {
	return {
		type: ValueType.Boolean,
		boolean: boolean,
	} as BooleanValue;
}

export function newRelation( id: string | undefined, target: SubjectId | string ): Relation {
	return new Relation(
		id,
		typeof target === 'string' ? new SubjectId( target ) : target,
	);
}

export function newUnregisteredTypeValue( typeName: string, raw: unknown ): UnregisteredTypeValue {
	return {
		type: ValueType.UnregisteredType,
		typeName: typeName,
		raw: raw,
	};
}

/**
 * Keeps the Relation, and with it the ID, of each target the current value points at. A target it does not
 * point at gets a new Relation.
 */
export function relationValueWithTargets( current: RelationValue | undefined, targets: string[] ): RelationValue {
	const unclaimed = [ ...( current?.relations ?? [] ) ];

	return new RelationValue( targets.map( ( target ) => {
		const index = unclaimed.findIndex( ( relation ) => relation.target.text === target );

		return index === -1 ? newRelation( undefined, target ) : unclaimed.splice( index, 1 )[ 0 ];
	} ) );
}

export function valueToJson( value: Value ): unknown {
	switch ( value.type ) {
		case ValueType.Url:
			return value.parts;
		case ValueType.String:
			return ( value as StringValue ).parts;
		case ValueType.Number:
			return ( value as NumberValue ).number;
		case ValueType.Boolean:
			return ( value as BooleanValue ).boolean;
		case ValueType.Relation:
			return ( value as RelationValue ).relations.map(
				( relation ) => ( { id: relation.id, target: relation.target.text } ),
			);
		case ValueType.MonolingualText:
			return ( value as MonolingualTextValue ).parts;
		case ValueType.UnregisteredType:
			return ( value as UnregisteredTypeValue ).raw;
		default:
			throw new Error( `Unsupported value type: ${ ( value as Value ).type }` );
	}
}

/**
 * Whether a Value carries no user content. Per-Value-Type:
 *   - String: empty parts array (or all parts trim to '').
 *   - Number/Boolean: never empty — 0 and false are legitimate values.
 *   - Relation: empty relations array.
 *   - MonolingualText: no parts left once the ones without text are dropped.
 *   - undefined: empty.
 */
export function isValueEmpty( value: Value | undefined ): boolean {
	if ( value === undefined ) {
		return true;
	}

	switch ( value.type ) {
		case ValueType.Url:
			return value.parts.length === 0;
		case ValueType.String:
			return value.parts.length === 0 ||
				value.parts.every( ( part ) => part.trim() === '' );
		case ValueType.Number:
		case ValueType.Boolean:
			return false;
		case ValueType.Relation:
			return value.relations.length === 0;
		case ValueType.MonolingualText:
			return value.parts.length === 0;
		case ValueType.UnregisteredType:
			return false;
		default:
			return true;
	}
}

/** A new form must never mutate schema defaults or another new form. */
export function cloneInitialValue( value: Value ): Value {
    if ( value instanceof RelationValue ) {
        return new RelationValue( value.relations.map( ( relation ) => new Relation( undefined, relation.target ) ) );
    }
    switch ( value.type ) {
        case ValueType.Url:
        case ValueType.MonolingualText:
            return { ...value, parts: value.parts.map( ( part ) => ( { ...part } ) ) } as Value;
        case ValueType.String:
            return { ...value, parts: [ ...value.parts ] };
        case ValueType.UnregisteredType:
            return { ...value, raw: value.raw === undefined ? undefined : JSON.parse( JSON.stringify( value.raw ) ) };
        default:
            return { ...value } as Value;
    }
}
